package com.sugarplumstudios.pinkified.client.gui;

import com.sugarplumstudios.pinkified.client.theme.ThemeId;
import com.sugarplumstudios.pinkified.client.util.Ids;
import net.minecraft.resources.Identifier;

/** Locations of Pinkified's own static textures (all generated by tools/assetgen). */
public final class PinkTextures {
    private PinkTextures() {
    }

    private static Identifier tex(String path) {
        return Ids.mod("textures/" + path + ".png");
    }

    public static final Identifier[] PETALS = {
            tex("gui/menu/petal_0"), tex("gui/menu/petal_1"), tex("gui/menu/petal_2"), tex("gui/menu/petal_3")};
    public static final int[][] PETAL_SIZES = {{7, 8}, {7, 7}, {5, 5}, {7, 8}};
    public static final Identifier SPARKLE_BIG = tex("gui/menu/sparkle_big");
    public static final Identifier SPARKLE_SMALL = tex("gui/menu/sparkle_small");
    public static final Identifier HEART = tex("gui/menu/heart");
    public static final Identifier BOW = tex("gui/menu/bow");
    public static final Identifier BOKEH = tex("gui/menu/bokeh");
    public static final Identifier[] CLOUDS = {tex("gui/menu/cloud_0"), tex("gui/menu/cloud_1")};
    public static final Identifier LOGO_BASE = tex("gui/logo/pinkified_base");
    public static final Identifier LOGO_GLOSS = tex("gui/logo/pinkified_gloss");
    public static final int LOGO_W = 104, LOGO_H = 29;

    public static final Identifier TAB_THEME = tex("gui/icons/tab_theme");
    public static final Identifier TAB_INTERFACE = tex("gui/icons/tab_interface");
    public static final Identifier TAB_HUD = tex("gui/icons/tab_hud");
    public static final Identifier TAB_EFFECTS = tex("gui/icons/tab_effects");
    public static final Identifier TAB_MOTION = tex("gui/icons/tab_motion");
    public static final Identifier TAB_AUDIO = tex("gui/icons/tab_audio");
    public static final Identifier HEART_BUTTON = tex("gui/icons/heart_button");
    public static final Identifier LANGUAGE = tex("gui/icons/language");
    public static final Identifier ACCESSIBILITY = tex("gui/icons/accessibility");

    public static Identifier themeIcon(ThemeId id) {
        return Ids.mod(id.iconPath());
    }
}
